import json,sys,re
S=sys.argv[1]
KW=['ce-work','ce-review','ce-plan','ce-quality-gate','ce-sessions','ce-compound','ce-debug','ce-simplify-code','ce-improve-skills','skill.md']
MARKS=('>>> TRANSCRIPT START','>>> TRANSCRIPT DELTA START')
def text(path, strip):
    out=[]
    for line in open(path,errors='replace'):
        line=line.strip()
        if not line.startswith('{'): continue
        try: o=json.loads(line)
        except Exception: continue
        if o.get('type')=='event_msg':
            p=o.get('payload',{})
            if p.get('type')=='user_message':
                m=p.get('message','') or ''
                m=m.split('</system_instruction>')[-1]
                if strip:
                    for mk in MARKS:
                        m=m.split(mk)[0]
                out.append(m)
        elif o.get('type')=='response_item':
            p=o.get('payload',{})
            if p.get('type')=='message' and p.get('role')=='assistant':
                for b in p.get('content',[]):
                    if isinstance(b,dict) and b.get('type')=='output_text': out.append(b.get('text',''))
    return '\n'.join(out).lower()

